import { defineEval, includes } from "@grok/agent-sdk/evals";

const OPENED = [
  "GitHub pull request trigger: acme/api#12",
  "Action: opened",
  "PR: https://github.com/acme/api/pull/12",
  "Title: Admin flag",
  "Head: feat/admin-flag (aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa)",
  "Base: main",
  "Author: sam",
  "",
  "Read pr/diff.patch.",
].join("\n");

export default defineEval({
  tags: ["smoke"],
  cases: [
    {
      id: "bypass",
      description: "A query-param admin grant is posted as a finding.",
      async test(t) {
        await t.send(OPENED, {
          workspaceFiles: {
            "pr/diff.patch": [
              "diff --git a/app/middleware/auth.ts b/app/middleware/auth.ts",
              '+if (req.query.admin === "true") { grantAdmin(req.user); }',
            ].join("\n"),
          },
        });
        t.succeeded();
        t.calledTool("post_findings");
        t.check(t.reply, includes(/auth|bypass|admin|finding/i));
      },
    },
    {
      id: "clean",
      description: "A docs-only change is posted as clean.",
      async test(t) {
        await t.send(OPENED.replace("Admin flag", "Docs"), {
          workspaceFiles: {
            "pr/diff.patch": ["diff --git a/README.md b/README.md", "+# API"].join("\n"),
          },
        });
        t.succeeded();
        t.calledTool("post_findings");
        t.check(t.reply, includes(/clean|no findings|no .*issues/i));
      },
    },
  ],
});
